    /**
     * Method to retrieve the Activity via ActivityFetchOneSummary
     * @param 	summary ActivityFetchOneSummary 
     * @return 	ActivityFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Activity getActivity( ActivityFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "ActivityFetchOneSummary arg cannot be null" );
    	
    	Activity entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Activity
        	// --------------------------------------
        	CompletableFuture<Activity> futureEntity = queryGateway.query(new FindActivityQuery( new LoadActivityFilter( summary.getActivityId() ) ), ResponseTypes.instanceOf(Activity.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Activity with id " + summary.getActivityId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


